const assert = require('node:assert')
const { execFileSync, spawnSync } = require('node:child_process')
const here = process.cwd()
const { createLimiter } = require(here + '/limiter.js')
let time = 1000
const now = () => time
const drain = (limiter, key) => { let n = 0; while (n < 100 && limiter.take(key)) n += 1; return n }
const limiter = createLimiter({ capacity: 3, refillPerSecond: 1, now })
assert.deepStrictEqual([1, 2, 3, 4].map(() => limiter.take('a')), [true, true, true, false])

